public static <T, R> boolean tryScalarXMapSubscribe(
        ObservableSource<T> source,
        Observer<? super R> observer,
        Function<? super T, ? extends ObservableSource<? extends R>> mapper) {
    SUPPORT.prepareScalarMapping(source, observer);
    if (source instanceof Supplier) {
        T t;
        try {
            t = ((Supplier<T>) source).get();
        } catch (Throwable ex) {
            Exceptions.throwIfFatal(ex);
            EmptyDisposable.error(ex, observer);
            return true;
        }
        if (t == null) {
            EmptyDisposable.complete(observer);
            return true;
        }
        ObservableSource<? extends R> mapped;
        try {
            mapped = Objects.requireNonNull(mapper.apply(t), "The mapper returned a null ObservableSource");
        } catch (Throwable ex) {
            Exceptions.throwIfFatal(ex);
            EmptyDisposable.error(ex, observer);
            return true;
        }
        if (mapped instanceof Supplier) {
            R u;
            try {
                u = ((Supplier<R>) mapped).get();
            } catch (Throwable ex) {
                Exceptions.throwIfFatal(ex);
                EmptyDisposable.error(ex, observer);
                return true;
            }
            if (u == null) {
                EmptyDisposable.complete(observer);
                return true;
            }
            ObservableScalarXMap.ScalarDisposable<R> sd = new ObservableScalarXMap.ScalarDisposable<>(observer, u);
            observer.onSubscribe(sd);
            sd.run();
        } else {
            mapped.subscribe(observer);
        }
        return true;
    }
    return false;
}

